INSERT INTO `traitors`(`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`,`Province`,`City`,`Country`,`Town`,`Village`,`MergedIntoId`,`MergedAt`,`BirthPlace`) VALUES ('6c801ca0c0701158cdb0af641779184b','汤炳如',NULL,NULL,NULL,NULL,'exact','exact','宜昌城区','[]','["日伪乡长、维持会长、情报所长、密侦大队长"]','1937-1945','','伪职：日伪乡长、维持会长、情报所长、密侦大队长；罪行：晓溪塔郭家冲汤家湾人，出身地主，人称汤三爷。1940年6月宜昌沦陷后投敌，先后任日伪乡长、维持会长、合作社事务员、情报所长、密侦大队长等职。在梅子垭设关卡，与日寇一起盘查过卡中国人，凡过卡者由日本哨兵先问汤“他们中国人的明白？”汤若点头即能过，若歪头即被当场杀死。兼任合作社事务员，大量税款流入其腰包。1941年至1943年间多次烧杀抢劫：烧毁张开余、胡少云、徐大金等人的房屋并杀人；指认龙书齐为情报员，被日军用狼狗活活咬死；杀害杨宏义一家四口','[]','2026-09-12 03:21:16.079990','2026-09-12 03:21:16.079990','','','',NULL,NULL,NULL,NULL,'');
