INSERT INTO `traitors`(`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`,`Province`,`City`,`Country`,`Town`,`Village`,`MergedIntoId`,`MergedAt`,`BirthPlace`) VALUES ('93700e3baa9341b0620c5026b29bb9c9','王继美',NULL,NULL,NULL,NULL,'exact','exact','山东枣庄；山西阳泉矿区；山东枣庄市中；山东枣庄；峄县（税郭）','[]','["伪峄县警备队队长、伪军头目", "伪枣庄矿区警备队队长", "伪宪兵队特务大队队长→峄东剿共司令→国民党32纵队司令", "税郭乡伪乡长"]','1938-1945；1939-1945；1937-1945','','伪职：伪峄县警备队队长、伪军头目；伪职：伪枣庄矿区警备队队长；伪职：伪宪兵队特务大队队长→峄东剿共司令→国民党32纵队司令；罪行：枣庄一带最知名的大汉奸。1919年生，郭里集前小湾人。1941年1月带全排28人携枪投降日军，被编入杨贵岭部，任峄县第三警备大队第三中队长兼税郭乡伪乡长。后任伪宪兵队特务大队队长、“峄东剿共司令”。残害抗日干部、战士及无辜百姓数百人。1944年制造“官地惨案”，偷袭鲁南军区警九旅十七团，致70余人牺牲、70余人被捕。日本投降后拒绝向八路军缴械，被国民党收编为“山东挺进军三十二纵队少将司令”。1946年6月枣庄首次解放时被击毙；结局：1946年6月9日在枣庄被山东野战军击毙；伪职：税郭乡伪乡长；罪行：兼任税郭乡伪乡长，驻防税郭，成为日军枣庄据点东部的屏障。1942年7月与当地汉奸、伪乡长联手为日军立“功德碑”；结局：见上','[]','2026-09-12 03:21:16.079990','2026-09-12 03:21:16.079990','山东','枣庄','山亭；市中',NULL,NULL,NULL,NULL,'');
INSERT INTO `traitors`(`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`,`Province`,`City`,`Country`,`Town`,`Village`,`MergedIntoId`,`MergedAt`,`BirthPlace`) VALUES ('f0c51c89c14193c569db5deb52fa7827','王济民',NULL,NULL,NULL,NULL,'exact','exact','江西上饶鄱阳','[]','["伪鄱阳县政府县长"]','1941-1945','','伪职：伪鄱阳县政府县长','[]','2026-09-12 03:21:16.079990','2026-09-12 03:21:16.079990','江西','上饶','鄱阳',NULL,NULL,NULL,NULL,'');
